jsonTools.init:
function init(eli) {
  function _esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function _launch() {
    var out = eli.ui.claimOutput();
    out.classList.add("eli-view-enter");
    if (out.style) { out.style.justifyContent = "flex-start"; out.style.alignItems = "stretch"; }
    out.innerHTML =
      '<div style="display:flex;flex-direction:column;min-height:100vh;background:#f8f9fa;font-family:Inter,sans-serif;">' +
        '<div style="display:flex;justify-content:space-between;align-items:center;padding:12px 16px;border-bottom:1px solid #e2e8f0;background:#fff;flex-shrink:0;">' +
          '<button id="_ig_back" type="button" style="background:none;border:none;color:#64748b;cursor:pointer;font:800 11px/1 Inter,sans-serif;letter-spacing:1px;display:flex;align-items:center;gap:6px;">' +
            '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M19 12H5M12 19l-7-7 7-7"/></svg> BACK' +
          '</button>' +
          '<div style="font:700 13px/1 Inter,sans-serif;color:#1565c0;">Infographics Lab</div>' +
        '</div>' +
        '<div style="padding:14px 16px;background:linear-gradient(135deg,#0d1b2a,#1b263b);color:#fff;">' +
          '<div style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.12em;text-transform:uppercase;color:#c9a227;">Admin · Test</div>' +
          '<div style="font:800 17px/1.2 Inter,sans-serif;margin-top:2px;">🎨 Infographic from live document</div>' +
        '</div>' +
        '<div style="padding:14px 16px;flex:1;overflow-y:auto;">' +
          '<div id="_ig_status" style="font:500 12px/1.4 Inter,sans-serif;color:#64748b;margin-bottom:10px;">' +
            'Click <b>Generate</b> to create an infographic of the active Word doc.' +
          '</div>' +
          '<div style="display:flex;gap:8px;align-items:center;margin-bottom:14px;">' +
            '<button id="_ig_run" type="button" style="font:800 11px/1 Inter,sans-serif;letter-spacing:0.5px;text-transform:uppercase;padding:10px 16px;background:#1565c0;color:#fff;border:none;cursor:pointer;">⚡ Generate</button>' +
            '<span id="_ig_model" style="font:500 11px/1.3 ui-monospace,Consolas,monospace;color:#94a3b8;"></span>' +
          '</div>' +
          '<div id="_ig_result_wrap" style="display:none;">' +
            '<div style="background:#fff;border:1px solid #e2e8f0;padding:14px;margin-bottom:14px;">' +
              '<img id="_ig_out" alt="generated infographic" style="display:block;max-width:100%;height:auto;border:1px dashed #cbd5e1;background:#f1f5f9;">' +
            '</div>' +
            '<div style="background:#fef3c7;border:1px solid #fde68a;padding:9px 12px;margin-bottom:10px;font:500 11px/1.5 Inter,sans-serif;color:#78350f;">' +
              '<b>💾 To save as a file:</b> right-click the image above → <b>Save image as…</b> → pick a location.' +
            '</div>' +
            '<div style="display:flex;flex-wrap:wrap;gap:8px;">' +
              '<button id="_ig_insert" type="button" style="font:700 11px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;padding:9px 13px;background:linear-gradient(135deg,#15803d,#166534);color:#fff;border:none;cursor:pointer;">📄 Insert into doc</button>' +
              '<button id="_ig_regen" type="button" style="font:700 11px/1 Inter,sans-serif;letter-spacing:0.4px;text-transform:uppercase;padding:9px 13px;background:#fff;border:1px solid #cbd5e1;color:#1e293b;cursor:pointer;">🔁 Regenerate</button>' +
            '</div>' +
          '</div>' +
        '</div>' +
      '</div>';

    document.getElementById("_ig_back").onclick = function () {
      if (typeof window.showHome === "function") window.showHome();
    };

    // Show which image model the AI will use, for debug visibility.
    try {
      var m = eli.settings && eli.settings.get && eli.settings.get("ai_image_model");
      document.getElementById("_ig_model").textContent = m
        ? "Model: " + m
        : "Model: (none set — go to Settings → 🖼 AI Image Model)";
    } catch (_e) {}

    // Preflight: kernel must be apiVersion 2+ for generateImage.
    if (!eli.ai || typeof eli.ai.generateImage !== "function") {
      _setStatus("⚠️ This tool needs kernel apiVersion 2 (image gen). Update your Script Lab snippet.", true);
      var btn = document.getElementById("_ig_run");
      btn.disabled = true; btn.style.opacity = "0.5";
      return;
    }

    document.getElementById("_ig_run").onclick = _generate;
    document.getElementById("_ig_regen").onclick = _generate;
    document.getElementById("_ig_insert").onclick = _insertIntoDoc;
    // 2026-05-25: Download + Copy buttons removed. Native browser
    // "Save image as…" (right-click) works in Office's WebView2 and
    // sidesteps two Script Lab limitations:
    //   • Anchor download (a[download]) fires but no file lands on disk
    //   • Clipboard API rejects image/jpeg (PNG only) and Gemini's
    //     image gen returns JPEG by default
  }

  function _setStatus(msg, isErr) {
    var el = document.getElementById("_ig_status");
    if (!el) return;
    el.innerHTML = msg;
    el.style.color = isErr ? "#b91c1c" : "#64748b";
  }

  function _generate() {
    var btn = document.getElementById("_ig_run");
    var regen = document.getElementById("_ig_regen");
    if (btn) { btn.disabled = true; btn.style.opacity = "0.5"; btn.textContent = "⏳ Working…"; }
    if (regen) { regen.disabled = true; regen.style.opacity = "0.5"; }
    _setStatus("⏳ Reading doc + calling image model…");

    eli.host.readText({}).then(function (text) {
      var clipped = String(text || "").slice(0, 2000);
      var prompt =
        "Create a clean, modern infographic visualizing the key elements of this legal contract. " +
        "Use simple icons, color-coded sections, clear hierarchy, and minimal text. " +
        "Highlight: parties, key dates, financial amounts, main obligations, and risk areas. " +
        "Style: corporate, premium, scannable at a glance.\n\n" +
        "CONTRACT EXCERPT:\n" + clipped;
      return eli.ai.generateImage(prompt);
    }).then(function (r) {
      window._igResult = r;
      var url = "data:" + (r.mimeType || "image/png") + ";base64," + r.base64;
      var img = document.getElementById("_ig_out");
      if (img) img.src = url;
      document.getElementById("_ig_result_wrap").style.display = "block";
      _setStatus("✅ Generated (" + (r.mimeType || "image/png") + ", " + r.base64.length + " base64 chars). Use the buttons below.");
    }).catch(function (err) {
      _setStatus("⚠️ " + _esc(err && err.message || "Image generation failed"), true);
      eli.log.event("tool", "infographics_lab_failed", { msg: err && err.message });
    }).then(function () {
      if (btn) { btn.disabled = false; btn.style.opacity = "1"; btn.textContent = "⚡ Generate"; }
      if (regen) { regen.disabled = false; regen.style.opacity = "1"; }
    });
  }

  function _insertIntoDoc() {
    var r = window._igResult; if (!r) return;
    if (typeof eli.host.insertImage !== "function") {
      _setStatus("⚠️ insertImage needs host apiVersion 4. Update your Script Lab snippet.", true);
      return;
    }
    eli.host.insertImage(r.base64, { position: "End" }).then(function () {
      if (window.showToast) window.showToast("✅ Inserted into doc", "ok");
    }).catch(function (err) {
      _setStatus("⚠️ Insert failed: " + _esc(err && err.message), true);
    });
  }

  eli.register({
    tile: { app_infographics_lab: _launch },
  });
  eli.log.event("tool", "infographics_lab_initialized", {});
}
